window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-bfa2b22eaf73e18a"]={"versions": [{"id": "FIG-bfa2b22eaf73e18a", "releases": ["R3.0.7", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Methodik-Ablaufdiagramm (AUTOSAR Methodology Activity Flow) zur Erzeugung von A2L-Dateien für Mess- und Kalibrierwerkzeuge (MCD). Der Prozess zeigt den Pfad von steuergerätespezifischen Konfigurationsbeschreibungen und extrahierten Software-Zusammensetzungen über die Glättung (Flattening) der Softwarestruktur bis zur Generierung der A2L-Datei unter Zuhilfenahme von Symbol-/Adressinformationen aus der Executable-Map.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivitäten / Prozessschritte (gelbe Blockpfeile):</strong>\n<ul class=\"fig-list\"><li><code>Generate flat description of SW per ECU</code> (ausführendes Werkzeug: <code>AUTOSAR flattener</code>).\n</li><li><code>Generate A2L</code> (ausführendes Werkzeug: <code>A2L Generator</code>).\n</li></ul>\n</li><li><strong>Werkzeuge (Lineal-Symbole, gestrichelt angebunden):</strong>\n<ul class=\"fig-list\"><li><code>AUTOSAR flattener</code>\n</li><li><code>A2L Generator</code>\n</li></ul>\n</li><li><strong>Artefakte / Work Products (blaue Dokument-Icons):</strong>\n<ul class=\"fig-list\"><li><code>ECU Configuration Description</code> (.XML)\n</li><li><code>ECU Software Composition : EcuSwComposition</code> (.XML)\n</li><li><code>BSW-Module Description</code> (.XML; Text unten abgeschnitten als BSW-Module ...)\n</li><li><code>Service Component</code> (.XML; Text unten abgeschnitten)\n</li><li><code>ECU Extract of System Configuration : System</code> (.XML)\n</li><li><code>ECU Extract of Top-Level Composition : CompositionType</code> (.XML)\n</li><li><code>Component Type</code> (.XML)\n</li><li><code>ECU flat description</code> (.XML)\n</li><li><code>MCD Configuration Description</code> (.XML)\n</li><li><code>Map of Executable</code> (Linker-Mapdatei / Adresszuordnung)\n</li><li><code>A2L</code> (ASAM MCD-2 MC Beschreibungsdatei)\n</li></ul>\n</li><li><strong>Beziehungen &amp; Kontroll-/Datenflüsse:</strong>\n<ul class=\"fig-list\"><li><code>ECU Configuration Description</code> dient als Eingangsartefakt für <code>Generate flat description of SW per ECU</code>.\n</li><li>Gestrichelte Pfeile referenzieren Teil- bzw. Unterstrukturen der Konfiguration: von <code>ECU Configuration Description</code> zu <code>BSW-Module Description</code>, <code>ECU Software Composition : EcuSwComposition</code> und <code>ECU Extract of System Configuration : System</code>.\n</li><li>Von <code>ECU Extract of System Configuration : System</code> führt eine gestrichelte Verfeinerung zu <code>ECU Extract of Top-Level Composition : CompositionType</code>, und von dort zu <code>Component Type</code>.\n</li><li>Pfeil von <code>Service Component</code> deutet auf <code>ECU Software Composition : EcuSwComposition</code>.\n</li><li><code>Generate flat description of SW per ECU</code> erzeugt die <code>ECU flat description</code> (.XML).\n</li><li><code>Generate A2L</code> nimmt als Eingänge die <code>ECU flat description</code> (.XML), die <code>MCD Configuration Description</code> (.XML) sowie die <code>Map of Executable</code> entgegen und generiert die finale <code>A2L</code>-Datei.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Bereitstellung der steuergerätespezifischen Ausgangsbeschreibungen (<code>ECU Configuration Description</code> zusammen mit den Software-Zusammensetzungen wie BSW-Modulen, Service Components und extrahierten System-/Top-Level-Kompositionen).\n</li><li>Der <code>AUTOSAR flattener</code> verarbeitet die Konfiguration in der Aktivität <code>Generate flat description of SW per ECU</code>, um eine aufgelöste, flache Repräsentation der Softwareelemente je Steuergerät (<code>ECU flat description</code>) zu erzeugen.\n</li><li>Der <code>A2L Generator</code> führt in der Aktivität <code>Generate A2L</code> die geglättete Softwarebeschreibung (<code>ECU flat description</code>) mit der <code>MCD Configuration Description</code> und den Adress-/Speicherortinformationen aus der <code>Map of Executable</code> zusammen.\n</li><li>Als finaler Output der Kette wird die standardisierte <code>A2L</code>-Datei für Mess- und Kalibriersysteme exportiert.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die A2L-Generierung bildet eine zentrale Brücke zwischen der AUTOSAR-Methodik und den standardisierten ASAM MCD-2 MC Kalibrierwerkzeugen. Für Entwickler und Tool-Ketten ist normativ relevant, dass die Software-Zusammensetzung vor der A2L-Generierung durch den Flattener aufgelöst werden muss, da A2L flache Adressräume und Mess-/Verstellgrößenbezeichner erfordert. Zudem ist die Synchronisation mit dem Linker-Map-File zwingend erforderlich, um den logischen AUTOSAR-Parametern und -Signalen reale Speicheradressen des kompilierten Steuergeräte-Binaries zuzuordnen.</p>"}, {"id": "FIG-d6d1c78c6807e6f3", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Methodik-Ablaufdiagramm (AUTOSAR Methodology Activity Flow) zur Erzeugung von A2L-Dateien für Mess- und Kalibrierwerkzeuge (MCD). Der Prozess zeigt den Pfad von steuergerätespezifischen Konfigurationsbeschreibungen und extrahierten Software-Zusammensetzungen über die Glättung (Flattening) der Softwarestruktur bis zur Generierung der A2L-Datei unter Zuhilfenahme von Symbol-/Adressinformationen aus der Executable-Map.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivitäten / Prozessschritte (gelbe Blockpfeile):</strong>\n<ul class=\"fig-list\"><li><code>Generate flat description of SW per ECU</code> (ausführendes Werkzeug: <code>AUTOSAR flattener</code>).\n</li><li><code>Generate A2L</code> (ausführendes Werkzeug: <code>A2L Generator</code>).\n</li></ul>\n</li><li><strong>Werkzeuge (Lineal-Symbole, gestrichelt angebunden):</strong>\n<ul class=\"fig-list\"><li><code>AUTOSAR flattener</code>\n</li><li><code>A2L Generator</code>\n</li></ul>\n</li><li><strong>Artefakte / Work Products (blaue Dokument-Icons):</strong>\n<ul class=\"fig-list\"><li><code>ECU Configuration Description</code> (.XML)\n</li><li><code>ECU Software Composition : EcuSwComposition</code> (.XML)\n</li><li><code>BSW-Module Description</code> (.XML; Text unten abgeschnitten als BSW-Module ...)\n</li><li><code>Service Component</code> (.XML; Text unten abgeschnitten)\n</li><li><code>ECU Extract of System Configuration : System</code> (.XML)\n</li><li><code>ECU Extract of Top-Level Composition : CompositionType</code> (.XML)\n</li><li><code>Component Type</code> (.XML)\n</li><li><code>ECU flat description</code> (.XML)\n</li><li><code>MCD Configuration Description</code> (.XML)\n</li><li><code>Map of Executable</code> (Linker-Mapdatei / Adresszuordnung)\n</li><li><code>A2L</code> (ASAM MCD-2 MC Beschreibungsdatei)\n</li></ul>\n</li><li><strong>Beziehungen &amp; Kontroll-/Datenflüsse:</strong>\n<ul class=\"fig-list\"><li><code>ECU Configuration Description</code> dient als Eingangsartefakt für <code>Generate flat description of SW per ECU</code>.\n</li><li>Gestrichelte Pfeile referenzieren Teil- bzw. Unterstrukturen der Konfiguration: von <code>ECU Configuration Description</code> zu <code>BSW-Module Description</code>, <code>ECU Software Composition : EcuSwComposition</code> und <code>ECU Extract of System Configuration : System</code>.\n</li><li>Von <code>ECU Extract of System Configuration : System</code> führt eine gestrichelte Verfeinerung zu <code>ECU Extract of Top-Level Composition : CompositionType</code>, und von dort zu <code>Component Type</code>.\n</li><li>Pfeil von <code>Service Component</code> deutet auf <code>ECU Software Composition : EcuSwComposition</code>.\n</li><li><code>Generate flat description of SW per ECU</code> erzeugt die <code>ECU flat description</code> (.XML).\n</li><li><code>Generate A2L</code> nimmt als Eingänge die <code>ECU flat description</code> (.XML), die <code>MCD Configuration Description</code> (.XML) sowie die <code>Map of Executable</code> entgegen und generiert die finale <code>A2L</code>-Datei.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Bereitstellung der steuergerätespezifischen Ausgangsbeschreibungen (<code>ECU Configuration Description</code> zusammen mit den Software-Zusammensetzungen wie BSW-Modulen, Service Components und extrahierten System-/Top-Level-Kompositionen).\n</li><li>Der <code>AUTOSAR flattener</code> verarbeitet die Konfiguration in der Aktivität <code>Generate flat description of SW per ECU</code>, um eine aufgelöste, flache Repräsentation der Softwareelemente je Steuergerät (<code>ECU flat description</code>) zu erzeugen.\n</li><li>Der <code>A2L Generator</code> führt in der Aktivität <code>Generate A2L</code> die geglättete Softwarebeschreibung (<code>ECU flat description</code>) mit der <code>MCD Configuration Description</code> und den Adress-/Speicherortinformationen aus der <code>Map of Executable</code> zusammen.\n</li><li>Als finaler Output der Kette wird die standardisierte <code>A2L</code>-Datei für Mess- und Kalibriersysteme exportiert.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die A2L-Generierung bildet eine zentrale Brücke zwischen der AUTOSAR-Methodik und den standardisierten ASAM MCD-2 MC Kalibrierwerkzeugen. Für Entwickler und Tool-Ketten ist normativ relevant, dass die Software-Zusammensetzung vor der A2L-Generierung durch den Flattener aufgelöst werden muss, da A2L flache Adressräume und Mess-/Verstellgrößenbezeichner erfordert. Zudem ist die Synchronisation mit dem Linker-Map-File zwingend erforderlich, um den logischen AUTOSAR-Parametern und -Signalen reale Speicheradressen des kompilierten Steuergeräte-Binaries zuzuordnen.</p>"}], "trans": [{"from": "FIG-bfa2b22eaf73e18a", "to": "FIG-d6d1c78c6807e6f3", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-d6d1c78c6807e6f3", "to": "FIG-bfa2b22eaf73e18a", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
